x, y := make([]float64, 101), make([]float64, 101)
for i := range x {
	x[i] = float64(i) * 2 * math.Pi / 100
	y[i] = math.Sin(x[i])
}
fmt.Printf("Sampled %d points\n", len(x))

err := chartframe.New("Sine wave").Labels("x (radians)", "sin(x)").Line("sin", x, y).Save("sine.svg")
if err != nil { panic(err) }
fmt.Println("Created sine.svg")
